  if(!data)return <p>Ładowanie raportu…</p>;
  return (
    <section>
      <h2>{data.title}</h2>
      <label><input type="checkbox" checked={autoRefresh} onChange={()=>setAutoRefresh(value=>!value)}/> Odświeżaj co 30 s</label>
